ALTER TABLE Session ADD COLUMN passkeyId VARCHAR(191) NULL;
CREATE TABLE Passkey (id VARCHAR(191) NOT NULL PRIMARY KEY,userId VARCHAR(191) NOT NULL,credentialId TEXT NOT NULL,credentialHash VARCHAR(191) NOT NULL,publicKey TEXT NOT NULL,counter BIGINT NOT NULL DEFAULT 0,label VARCHAR(191) NOT NULL,createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),revokedAt DATETIME(3) NULL,UNIQUE KEY Passkey_credentialHash_key(credentialHash),INDEX Passkey_userId_idx(userId)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE PasskeyChallenge (id VARCHAR(191) NOT NULL PRIMARY KEY,userId VARCHAR(191) NULL,challenge VARCHAR(191) NOT NULL,kind VARCHAR(191) NOT NULL,expiresAt DATETIME(3) NOT NULL,consumed BOOLEAN NOT NULL DEFAULT false) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
